"""Local, dependency-free before/after review of native game views."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'build/landscape-review'
rows=json.loads((root/'manifest.json').read_text())
for row in rows:
    for phase in ['before','after']:
        assert (root/phase/row['file']).is_file()
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Frostmere · Towns & landscapes</title>
<style>*{box-sizing:border-box}body{margin:0;background:#111c20;color:#e9e5d9;font:16px system-ui}header{padding:42px 5vw;background:linear-gradient(120deg,#324f47,#1b2935)}h1{font:44px Georgia;margin:14px 0}p{max-width:850px;line-height:1.6;color:#cbd1c9}small{color:#d8b77a;letter-spacing:2px}nav{position:sticky;top:0;z-index:1;padding:16px 5vw;background:#142126ed;display:flex;flex-wrap:wrap;gap:12px}button,select{font:inherit;padding:10px;background:#293c3b;border:1px solid #6d8580;color:#eee7d9;border-radius:5px;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #e2b678}main{padding:24px 5vw}#grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:22px}article{background:#203136;border:1px solid #425853;border-radius:8px;overflow:hidden}article button{padding:0;width:100%;border:0;border-radius:0}img{display:block;width:100%;aspect-ratio:1.6;object-fit:contain}article div{padding:16px}h2{font:24px Georgia;margin:9px 0}dialog{width:1360px;max-width:96vw;background:#142126;color:#eee7d9;border:1px solid #6d8580;border-radius:8px}dialog::backdrop{background:#000d}footer{display:flex;gap:10px;align-items:center;justify-content:space-between;padding-top:12px}a{color:#e3c689}</style>
<header><small>FROSTMERE · WORLD POLISH REVIEW</small><h1>Towns with a landscape.</h1><p>26 matching viewpoints across 12 regions and destinations. Compare the previous scenery with the current in-game terrain, foliage, town dressing, water and atmosphere.</p><p>Use Before / After to compare the same camera position. Click any view to enlarge it; arrow keys move through the selected region. <a href="../../docs/reference/approved-concept.png">Original concept</a> · <a href="../building-review/index.html">Architecture review</a></p></header>
<nav><select id="region" aria-label="Region"><option value="all">All regions</option></select><select id="phase" aria-label="Before or after"><option value="after">After · current game</option><option value="before">Before · previous scenery</option></select><span id="count"></span></nav><main><div id="grid"></div></main><dialog id="viewer"><img id="large" alt=""><footer><button id="prev">← Previous</button><span id="caption"></span><button id="compare">Show before</button><button id="next">Next →</button><button id="close">Close</button></footer></dialog>
<script>
const data=__DATA__,names={frostmere:'Frostmere',mountain:'Wyrmkeep',archive_chapter:'Pinehall',shore:'Saltbreak',lens:'Sunken Lens',roots:'Amberweald',choir:'Ember Caldera',convergence:'Mirewatch',winter:'Northwatch',threshold:'First Threshold',aeralis:'Aeralis',crucible:'The Crucible'},$=x=>document.getElementById(x);let shown=data,active=0,phase='after';
for(const id of [...new Set(data.map(r=>r.region))]){const o=document.createElement('option');o.value=id;o.textContent=names[id];$('region').append(o)}
function refreshModal(){const r=shown[active];$('large').src=phase+'/'+r.file;$('large').alt=r.title+' · '+phase;$('caption').textContent=names[r.region]+' — '+r.title+' · '+phase;$('compare').textContent=phase==='after'?'Show before':'Show after'}
function show(i){active=(i+shown.length)%shown.length;phase=$('phase').value;refreshModal();if(!$('viewer').open)$('viewer').showModal()}
function draw(){shown=data.filter(r=>$('region').value==='all'||r.region===$('region').value);$('count').textContent=shown.length+' views';$('grid').replaceChildren();shown.forEach((r,i)=>{const a=document.createElement('article'),b=document.createElement('button'),img=document.createElement('img'),d=document.createElement('div'),s=document.createElement('small'),h=document.createElement('h2');img.src=$('phase').value+'/'+r.file;img.alt=r.title;img.loading='lazy';b.setAttribute('aria-label','Enlarge '+r.title);b.onclick=()=>show(i);s.textContent=names[r.region];h.textContent=r.title;b.append(img);d.append(s,h);a.append(b,d);$('grid').append(a)})}
$('region').onchange=draw;$('phase').onchange=draw;$('prev').onclick=()=>show(active-1);$('next').onclick=()=>show(active+1);$('compare').onclick=()=>{phase=phase==='after'?'before':'after';refreshModal()};$('close').onclick=()=>$('viewer').close();document.onkeydown=e=>{if(!$('viewer').open)return;if(e.key==='ArrowLeft')show(active-1);if(e.key==='ArrowRight')show(active+1)};draw();
</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',json.dumps(rows).replace('</','<\\/')))
print(f'LANDSCAPE_GALLERY_COMPLETE {len(rows)} paired views')
